pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= address(c).balance);
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}("");
        vm.assume(success);
        vm.prank(address(this));
        c.smartfix_owner();
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
        assertTrue(ok && address(c).balance == 0);
    }
}

