// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 initialBalance) public {
        // Bound initial balance to a reasonable range
        initialBalance = bound(initialBalance, 0, 100 ether);
        vm.assume(caller == c.smartfix_owner()); // Only run when caller is the owner

        // Set up initial balance
        vm.deal(address(c), initialBalance);

        // Record balance before call
        uint256 balanceBefore = address(c).balance;

        // Call by owner
        vm.prank(caller);
        c.sudicideAnyone();

        // Rule: after selfdestruct, if the target was msg.sender (reference C), balance becomes zero
        // But in the mutant (target address(0)), balance remains unchanged.
        // We check the reference behavior: balance equals initial balance (because reference sends all to msg.sender, not to itself)
        // Actually in reference, the balance goes to msg.sender, so address(c).balance becomes 0
        // In mutant, balance stays at initialBalance (since selfdestruct to address(0) burns the balance)
        // We assert the reference property: balanceAfter == 0
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceBefore == initialBalance && balanceAfter == 0, "Reference: balance goes to zero after selfdestruct to owner");
    }
}

