pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 initialBalance) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.deal(address(c), initialBalance);
        vm.prank(caller);
        if (caller != c.smartfix_owner()) {
            vm.expectRevert();
            c.sudicideAnyone();
            return;
        }
        c.sudicideAnyone();
        // After self-destruct, the contract has zero balance.
        assertTrue(address(c).balance == 0);
    }
}

